CREATE OR REPLACE FUNCTION public.commerce_assign_storefront_customer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.source_channel = 'storefront' AND NEW.customer_id IS NULL AND NEW.user_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.commerce_customers WHERE id = NEW.user_id) THEN
    NEW.customer_id := NEW.user_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.commerce_ordinary_immutable_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'commerce_orders' THEN
    IF OLD.payment_route IS NOT NULL AND NEW.payment_route IS DISTINCT FROM OLD.payment_route THEN
      RAISE EXCEPTION 'payment route is immutable';
    END IF;
  ELSIF TG_TABLE_NAME = 'commerce_payments' THEN
    IF OLD.payment_channel = 'ordinary_wechat' AND
      (NEW.order_id,NEW.payment_channel,NEW.merchant_order_no,NEW.payer_openid,NEW.merchant_snapshot,NEW.amount,NEW.currency)
      IS DISTINCT FROM
      (OLD.order_id,OLD.payment_channel,OLD.merchant_order_no,OLD.payer_openid,OLD.merchant_snapshot,OLD.amount,OLD.currency) THEN
      RAISE EXCEPTION 'payment snapshot is immutable';
    END IF;
  ELSE
    IF OLD.merchant_refund_no IS NOT NULL AND
      (NEW.order_id,NEW.payment_id,NEW.after_sale_id,NEW.merchant_refund_no,NEW.route_snapshot,NEW.amount)
      IS DISTINCT FROM
      (OLD.order_id,OLD.payment_id,OLD.after_sale_id,OLD.merchant_refund_no,OLD.route_snapshot,OLD.amount) THEN
      RAISE EXCEPTION 'refund snapshot is immutable';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.commerce_resolve_order_coupon()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.payment_status IN ('paid','partially_refunded','refunded') THEN
    UPDATE public.pos_customer_coupons SET status='used',updated_at=now() WHERE reserved_order_id=NEW.id AND status='reserved';
  ELSIF NEW.payment_status='unpaid' AND NEW.order_status IN ('cancelled','closed') THEN
    UPDATE public.pos_customer_coupons SET status=CASE WHEN expires_at IS NOT NULL AND expires_at<=now() THEN 'expired' ELSE 'active' END,
      reserved_order_id=NULL,updated_at=now() WHERE reserved_order_id=NEW.id AND status='reserved';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_inv_skus_derive_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_custom_price = true OR NEW.kind = 'pack' THEN
    NEW.sku_scope := 'custom';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_inv_skus_fill_barcode()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  candidate text;
  attempts int := 0;
BEGIN
  IF NEW.barcode IS NOT NULL THEN RETURN NEW; END IF;
  LOOP
    candidate := public.gen_ean13();
    PERFORM 1 FROM public.inv_skus WHERE barcode = candidate;
    IF NOT FOUND THEN
      NEW.barcode := candidate;
      RETURN NEW;
    END IF;
    attempts := attempts + 1;
    IF attempts > 10 THEN
      RAISE EXCEPTION 'failed to generate unique EAN-13 after 10 attempts';
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.youzan_image_refresh_on_images()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.image_paths IS DISTINCT FROM OLD.image_paths OR NEW.image_url IS DISTINCT FROM OLD.image_url THEN
    PERFORM youzan_image_refresh_enqueue(NEW.id);
  END IF;
  RETURN NEW;
END;
$function$
